 /** Parse a URL query string. See README.md for the rules. */
 export function parseQuery(query: string): Query {
-  throw new Error("not implemented");
+  const body = query.startsWith("?") ? query.slice(1) : query;
+  const collected = new Map<string, string[]>();
+
+  for (const pair of body.split("&")) {
+    if (pair === "") continue;
+    const eq = pair.indexOf("=");
+    const key = decodePart(eq === -1 ? pair : pair.slice(0, eq));
+    const value = decodePart(eq === -1 ? "" : pair.slice(eq + 1));
+    const values = collected.get(key);
+    if (values) values.push(value);
+    else collected.set(key, [value]);
+  }
+
+  // Object.fromEntries defines own properties, so keys like "__proto__" stay plain data.
+  return Object.fromEntries(
+    [...collected].map(([key, values]): [string, string | string[]] => [
+      key,
+      values.length === 1 ? values[0] : values,
+    ]),
+  );
 }
+
+function decodePart(part: string): string {
+  const spaced = part.replaceAll("+", " ");
+  try {
+    return decodeURIComponent(spaced);
+  } catch {
+    return spaced;
+  }
+}
